CREATE OR REPLACE FUNCTION public.contact_verification_can_access(p_store_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.store_master WHERE id=p_store_id AND deleted_at IS NULL) AND (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'admin') OR public.va_can_access_store(p_store_id) OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('employee','staff','csr')) OR (public.has_role(auth.uid(),'ambassador') AND public.ambassador_has_store_access(auth.uid(),p_store_id)) OR EXISTS(SELECT 1 FROM public.routes r JOIN public.route_stops s ON s.route_id=r.id WHERE s.store_id=p_store_id AND r.assigned_to=auth.uid() AND r.status NOT IN ('cancelled','canceled')) OR ((public.has_role(auth.uid(),'driver') OR public.has_role(auth.uid(),'biker')) AND public.user_has_store_access(p_store_id))) $$;
CREATE OR REPLACE FUNCTION public.contact_verification_record_call(p_contact_id uuid,p_outcome text,p_attempt_id uuid,p_started_at timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.store_contacts%ROWTYPE; log_id uuid; BEGIN SELECT * INTO c FROM public.store_contacts WHERE id=p_contact_id AND deleted_at IS NULL FOR UPDATE; IF c.id IS NULL OR NOT public.contact_verification_can_access(c.store_id) THEN RAISE EXCEPTION 'Not authorized for this contact'; END IF; IF p_outcome NOT IN ('answered','no_answer','voicemail','wrong_number','disconnected') OR p_attempt_id IS NULL OR p_started_at IS NULL OR p_started_at>now() OR p_started_at<now()-interval '4 hours' THEN RAISE EXCEPTION 'Invalid call outcome or time'; END IF; IF EXISTS(SELECT 1 FROM public.communication_logs WHERE idempotency_key='contact-call-'||p_attempt_id AND contact_id=c.id) THEN RETURN; END IF; SELECT id INTO log_id FROM public.communication_logs WHERE contact_id=c.id AND store_id=c.store_id AND channel='call' AND direction='outbound' AND created_at>=p_started_at AND created_by=auth.uid() AND coalesce(idempotency_key,'') NOT LIKE 'contact-call-%' ORDER BY created_at DESC LIMIT 1; IF log_id IS NULL THEN PERFORM public.contact_verification_call_outcome(p_contact_id,p_outcome,p_attempt_id); RETURN; END IF; UPDATE public.communication_logs SET outcome=p_outcome,idempotency_key='contact-call-'||p_attempt_id WHERE id=log_id; PERFORM public.update_contact_responsiveness(c.id); UPDATE public.store_contacts SET last_call_outcome=p_outcome,updated_by=auth.uid() WHERE id=c.id; INSERT INTO public.store_notes(store_id,note_text,note_date,created_by,source) VALUES(c.store_id,'Contact verification: '||c.name||' ('||c.phone||'), call outcome: '||replace(p_outcome,'_',' ')||' at '||to_char(now(),'YYYY-MM-DD HH24:MI TZ'),current_date,auth.uid(),'in_person_verification'); END $$;
REVOKE ALL ON FUNCTION public.contact_verification_record_call(uuid,text,uuid,timestamptz) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.contact_verification_record_call(uuid,text,uuid,timestamptz) TO authenticated;